const response = $input.first().json;

if (!response || !response.hourly || !Array.isArray(response.hourly.time)) {
  throw new Error('Open-Meteo API response does not contain hourly data.');
}

const hourly = response.hourly;
const daily = response.daily || {};
const hourlyLen = hourly.time.length;

// สร้าง Map ของ Sun Data
const sunMap = {};
if (daily.time && Array.isArray(daily.time)) {
  for (let i = 0; i < daily.time.length; i++) {
    const dStr = daily.time[i];
    sunMap[dStr] = {
      sunrise: daily.sunrise && daily.sunrise[i] ? `${daily.sunrise[i]}:00+07:00` : null,
      sunset: daily.sunset && daily.sunset[i] ? `${daily.sunset[i]}:00+07:00` : null
    };
  }
}

const getConditionText = (code) => {
  switch (Number(code)) {
    case 0: return 'ท้องฟ้าแจ่มใส';
    case 1: return 'มีเมฆเล็กน้อย';
    case 2: return 'มีเมฆบางส่วน';
    case 3: return 'เมฆมาก';
    case 45:
    case 48: return 'มีหมอก';
    case 51:
    case 53:
    case 55: return 'ฝนปรอย';
    case 61:
    case 63:
    case 65: return 'ฝนตก';
    case 80:
    case 81:
    case 82: return 'ฝนซู่';
    case 95:
    case 96:
    case 99: return 'พายุฝนฟ้าคะนอง';
    default: return `สภาพอากาศรหัส ${code}`;
  }
};

const results = [];
for (let i = 0; i < hourlyLen; i++) {
  const rawTime = hourly.time[i];
  if (!rawTime) continue;

  const formattedTime = rawTime.includes('+') ? rawTime : `${rawTime}:00+07:00`;
  const dateKey = rawTime.split('T')[0];
  const sunInfo = sunMap[dateKey] || { sunrise: null, sunset: null };

  results.push({
    json: {
      location: 'Chiang Mai',
      latitude: 18.7883,
      longitude: 98.9853,
      date: dateKey,
      forecast_time: formattedTime,
      temperature: hourly.temperature_2m && hourly.temperature_2m[i] !== null ? Number(hourly.temperature_2m[i]) : null,
      humidity: hourly.relative_humidity_2m && hourly.relative_humidity_2m[i] !== null ? Number(hourly.relative_humidity_2m[i]) : null,
      rainfall: hourly.precipitation && hourly.precipitation[i] !== null ? Number(hourly.precipitation[i]) : 0,
      rain_probability: hourly.precipitation_probability && hourly.precipitation_probability[i] !== null ? Number(hourly.precipitation_probability[i]) : 0,
      wind_speed: hourly.wind_speed_10m && hourly.wind_speed_10m[i] !== null ? Number(hourly.wind_speed_10m[i]) : null,
      wind_direction: hourly.wind_direction_10m && hourly.wind_direction_10m[i] !== null ? String(hourly.wind_direction_10m[i]) : null,
      pressure: hourly.surface_pressure && hourly.surface_pressure[i] !== null ? Number(hourly.surface_pressure[i]) : null,
      cloud_cover: hourly.cloud_cover && hourly.cloud_cover[i] !== null ? Number(hourly.cloud_cover[i]) : null,
      weather_condition: getConditionText(hourly.weather_code ? hourly.weather_code[i] : null),
      sunrise: sunInfo.sunrise,
      sunset: sunInfo.sunset,
      source: 'Open-Meteo'
    }
  });
}

return results;
